style.css:
@-moz-document domain("tryhackme.com") {
/* Main background */
html,
body,
#__next,
.app,
main {
    background: #050505 !important;
    color: #e5e5e5 !important;
}

/* General containers/cards */
div,
section,
article,
aside,
nav,
header,
footer {
    border-color: #1a1a1a !important;
}

/* Cards / panels */
[class*="card"],
[class*="Card"],
[class*="box"],
[class*="Box"],
[class*="container"],
[class*="Container"],
[class*="panel"],
[class*="Panel"] {
    background: #0b0b0b !important;
    color: #e5e5e5 !important;
    border-color: #1f1f1f !important;
    box-shadow: 0 0 18px rgba(0, 255, 140, 0.04) !important;
}

/* Top nav / sidebars */
nav,
header,
[class*="sidebar"],
[class*="Sidebar"],
[class*="navbar"],
[class*="Navbar"] {
    background: #070707 !important;
    color: #f0f0f0 !important;
    border-color: #1a1a1a !important;
}

/* Text */
p,
span,
h1,
h2,
h3,
h4,
h5,
h6,
li,
label {
    color: #e5e5e5 !important;
}

/* Muted text */
small,
[class*="muted"],
[class*="secondary"],
[class*="description"] {
    color: #9ca3af !important;
}

/* Links */
a {
    color: #00ff99 !important;
    text-decoration: none !important;
}

a:hover {
    color: #7cffc4 !important;
    text-shadow: 0 0 8px rgba(0, 255, 153, 0.35) !important;
}

/* Buttons */
button,
[class*="button"],
[class*="Button"] {
    background: #111111 !important;
    color: #f5f5f5 !important;
    border: 1px solid #2a2a2a !important;
    border-radius: 10px !important;
}

button:hover,
[class*="button"]:hover,
[class*="Button"]:hover {
    background: #151515 !important;
    border-color: #00ff99 !important;
    box-shadow: 0 0 12px rgba(0, 255, 153, 0.25) !important;
}

/* Primary/accent buttons */
button[type="submit"],
[class*="primary"],
[class*="Primary"] {
    background: linear-gradient(135deg, #00c878, #00995c) !important;
    color: #020202 !important;
    border: none !important;
    font-weight: 700 !important;
}

/* Inputs */
input,
textarea,
select {
    background: #090909 !important;
    color: #e5e5e5 !important;
    border: 1px solid #262626 !important;
    border-radius: 8px !important;
}

input:focus,
textarea:focus,
select:focus {
    outline: none !important;
    border-color: #00ff99 !important;
    box-shadow: 0 0 0 2px rgba(0, 255, 153, 0.18) !important;
}

/* Code blocks / terminals */
pre,
code,
[class*="terminal"],
[class*="Terminal"],
[class*="code"],
[class*="Code"] {
    background: #030303 !important;
    color: #00ff99 !important;
    border-color: #1f1f1f !important;
}

/* Tables */
table,
thead,
tbody,
tr,
td,
th {
    background: #080808 !important;
    color: #e5e5e5 !important;
    border-color: #1f1f1f !important;
}

/* Progress bars */
progress,
[class*="progress"],
[class*="Progress"] {
    accent-color: #00ff99 !important;
}

/* Badges / tags */
[class*="badge"],
[class*="Badge"],
[class*="tag"],
[class*="Tag"] {
    background: #101010 !important;
    color: #00ff99 !important;
    border: 1px solid #1f1f1f !important;
    border-radius: 999px !important;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px !important;
    height: 10px !important;
}

::-webkit-scrollbar-track {
    background: #050505 !important;
}

::-webkit-scrollbar-thumb {
    background: #242424 !important;
    border-radius: 999px !important;
}

::-webkit-scrollbar-thumb:hover {
    background: #00a864 !important;
}

/* Images slightly softened */
img {
    filter: brightness(0.9) contrast(1.05) !important;
}

/* Remove annoying pure white backgrounds */
[style*="background: white"],
[style*="background-color: white"],
[style*="background:#fff"],
[style*="background-color:#fff"],
[style*="background: #fff"],
[style*="background-color: #fff"] {
    background: #0b0b0b !important;
}

/* Selection color */
::selection {
    background: rgba(0, 255, 153, 0.35) !important;
    color: #ffffff !important;
}
}
